    read: vi.fn(async (buf, offset, len, pos) => {
      buf.write("DATA", offset);
      return { bytesRead: 4 };
    }),
    close,
  };
  return {
    io: {
      lstat: vi.fn(async () => stat(4)),
      open: vi.fn(async () => handle),
      unlink,
    },
    handle,
    unlink,
  };
}

describe("readImageSnapshot failure cleanup", () => {
  it("returns exact bytes on success, closes the handle once and never deletes the file", async () => {
    const { io, handle, unlink } = baseIo();
    const result = await readImageSnapshot("/attachments/a.png", 4, { io });
    expect(result.equals(Buffer.from("DATA"))).toBe(true);
    expect(handle.close).toHaveBeenCalledTimes(1);
    expect(unlink).not.toHaveBeenCalled();
    expect(io.open).toHaveBeenCalledTimes(1);
  });

  it("closes the handle and keeps the file when a read throws", async () => {
    const { io, handle, unlink } = baseIo();
    handle.read.mockRejectedValueOnce(new Error("disk read failed"));
    await expect(
      readImageSnapshot("/attachments/a.png", 4, { io }),
    ).rejects.toThrow("disk read failed");
    expect(handle.close).toHaveBeenCalledTimes(1);
    expect(unlink).not.toHaveBeenCalled();
  });

  it("closes the handle and keeps the file when the read is aborted", async () => {
    const { io, handle, unlink } = baseIo();
    const controller = new AbortController();
    // Abort after the handle is open but before the next boundary check.
    handle.stat.mockImplementationOnce(async () => {
      controller.abort();
      return stat(4);
    });
    await expect(
      readImageSnapshot("/attachments/a.png", 4, {
        io,
        signal: controller.signal,
      }),
    ).rejects.toThrow("Image reading cancelled");
    expect(handle.close).toHaveBeenCalledTimes(1);
    expect(unlink).not.toHaveBeenCalled();
  });

  it("closes the handle and keeps the file when the time budget is exceeded", async () => {
    const { io, handle, unlink } = baseIo();
    let t = 0;
    const now = () => (t += 100);
    await expect(
      readImageSnapshot("/attachments/a.png", 4, {
        io,
        timeoutMs: 500,
        now,
      }),
    ).rejects.toThrow("Image reading exceeded the time budget");
    expect(handle.close).toHaveBeenCalledTimes(1);
    expect(unlink).not.toHaveBeenCalled();
  });

  it("closes the handle and keeps the file when the attachment changes while reading", async () => {
    const { io, handle, unlink } = baseIo();
    // The post-read path check reports a different size than the opened handle.
    let lstatCalls = 0;
    io.lstat.mockImplementation(async () => {
      lstatCalls += 1;
      return lstatCalls === 1 ? stat(4) : stat(5);
    });
    await expect(
      readImageSnapshot("/attachments/a.png", 4, { io }),
    ).rejects.toThrow("Saved attachment changed while reading");
    expect(handle.close).toHaveBeenCalledTimes(1);
    expect(unlink).not.toHaveBeenCalled();
  });

  it("never opens a handle or deletes the file when the attachment is missing or changed", async () => {
    const { io, handle, unlink } = baseIo();
    io.lstat.mockResolvedValue({ isFile: () => false });
    await expect(
      readImageSnapshot("/attachments/a.png", 4, { io }),
    ).rejects.toThrow("Saved attachment is missing or changed");
    expect(handle.close).not.toHaveBeenCalled();
    expect(io.open).not.toHaveBeenCalled();
    expect(unlink).not.toHaveBeenCalled();
  });
});

const fs = require("fs/promises");
const { constants } = require("fs");

// Fixed allocation + one overflow byte. Reads, hash and validation consume the
// same snapshot; no unbounded readFile after a separate header/path check.
async function readImageSnapshot(
  file,
  expectedSize = null,
  { io = fs, signal, timeoutMs = 5000, now = () => performance.now() } = {},
) {
  const deadline = now() + timeoutMs;
  const check = () => {
    if (signal?.aborted) throw new Error("Image reading cancelled");
    if (now() >= deadline)
      throw new Error("Image reading exceeded the time budget");
  };
  const same = (a, b) =>
    a.isFile() &&
    b.isFile() &&
    ["size", "dev", "ino", "mtimeMs", "ctimeMs"].every(
      (key) => a[key] === b[key],
    );
  check();
  const before = await io.lstat(file);
  check();
  if (
    !before.isFile() ||
    before.size <= 0 ||
    before.size > 20 * 1024 * 1024 ||
    (expectedSize !== null && before.size !== expectedSize)
  )
    throw new Error("Saved attachment is missing or changed; attach it again");
  const handle = await io.open(
    file,
    constants.O_RDONLY | (constants.O_NOFOLLOW || 0),
  );
  try {
    check();
    const opened = await handle.stat();
    if (!same(before, opened))
      throw new Error("Saved attachment changed while opening");
    const buffer = Buffer.alloc(opened.size + 1);
    let count = 0;
    while (count < buffer.length) {
      check();
      const { bytesRead } = await handle.read(
        buffer,
        count,
        Math.min(64 * 1024, buffer.length - count),
        count,
      );
      check();
      if (!bytesRead) break;
      count += bytesRead;
    }
    const after = await handle.stat();
    const pathAfter = await io.lstat(file);
    check();
    if (
      count !== opened.size ||
      !same(opened, after) ||
      !same(opened, pathAfter)
    )
      throw new Error("Saved attachment changed while reading");
    return buffer.subarray(0, count);
  } finally {
    await handle.close();
  }
}

module.exports = { readImageSnapshot };

