  it("restores the short text backup across Webview reload and blocks missing images", async () => {
    const key = "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa";
    const ui = webview({
      draftTextBackup: { key, text: "last keystroke", pendingId: null },
